insert into public.questions(id,section,type,text,options,correct,explanation,points) values
(1,'Partie 1 — Comprendre la bancassurance en Tunisie','single','La bancassurance désigne :','[{"id":"a","label":"La création d’une banque par une compagnie d’assurance"},{"id":"b","label":"La distribution de produits d’assurance par le réseau d’une banque, dans le cadre d’un partenariat avec une compagnie d’assurance"},{"id":"c","label":"La vente de produits bancaires par un agent général d’assurance"},{"id":"d","label":"Le rachat d’un contrat d’assurance-vie auprès d’une banque"}]','["b"]','Module 1.1 — Définition et principe.',1),
(2,'Partie 1 — Comprendre la bancassurance en Tunisie','single','Pour le commercial d’une compagnie d’assurance, la banque doit être considérée comme :','[{"id":"a","label":"Un concurrent direct du réseau d’agents et de courtiers"},{"id":"b","label":"Un canal de distribution complémentaire au réseau d’agents et de courtiers"},{"id":"c","label":"Un simple apporteur d’affaires occasionnel"},{"id":"d","label":"Le porteur du risque à la place de la compagnie"}]','["b"]','Module 1.1 — La banque est un canal complémentaire, pas un concurrent.',1),
(3,'Partie 1 — Comprendre la bancassurance en Tunisie','single','Dans le modèle « filiale d’assurance dédiée » :','[{"id":"a","label":"Une compagnie indépendante signe une convention avec plusieurs banques"},{"id":"b","label":"La banque crée ou détient une compagnie d’assurance qui conçoit des produits pour son propre réseau"},{"id":"c","label":"La banque agit uniquement comme courtier rémunéré à la commission"},{"id":"d","label":"La compagnie d’assurance devient actionnaire majoritaire de la banque"}]','["b"]','Module 1.2 — Modèle intégré, forte dépendance au réseau bancaire actionnaire.',1),
(4,'Partie 1 — Comprendre la bancassurance en Tunisie','single','Aujourd’hui, le principal moteur de la bancassurance en Tunisie est :','[{"id":"a","label":"L’assurance voyage liée aux cartes bancaires"},{"id":"b","label":"L’assurance emprunteur liée au crédit immobilier et au crédit à la consommation"},{"id":"c","label":"L’assurance automobile"},{"id":"d","label":"Les produits Takaful"}]','["b"]','Module 1.3 — Poids et tendances du marché.',1),
(5,'Partie 2 — Cadre juridique et réglementaire','single','Le cadre légal de référence du secteur des assurances en Tunisie est :','[{"id":"a","label":"La loi n° 92-24 du 9 mars 1992, modifiée à plusieurs reprises"},{"id":"b","label":"Le Code de commerce tunisien"},{"id":"c","label":"Une circulaire de la Banque Centrale de Tunisie"},{"id":"d","label":"La loi de finances annuelle"}]','["a"]','Module 2.1 — Code des Assurances tunisien.',1),
(6,'Partie 2 — Cadre juridique et réglementaire','single','Le Comité Général des Assurances (CGA) est placé sous l’autorité :','[{"id":"a","label":"De la Banque Centrale de Tunisie"},{"id":"b","label":"Du ministère des Finances"},{"id":"c","label":"Du ministère du Commerce"},{"id":"d","label":"De la Fédération tunisienne des sociétés d’assurances"}]','["b"]','Module 2.2 — Organe de tutelle et de contrôle du secteur.',1),
(7,'Partie 2 — Cadre juridique et réglementaire','multiple','Parmi les missions suivantes, lesquelles relèvent du CGA ?','[{"id":"a","label":"L’agrément des compagnies d’assurance et le contrôle de leur solvabilité"},{"id":"b","label":"L’encadrement des conditions d’exercice de l’intermédiation, y compris en bancassurance"},{"id":"c","label":"La fixation des taux d’intérêt des crédits bancaires"},{"id":"d","label":"La validation des conditions générales et des tarifs de certains produits"}]','["a","b","d"]','Module 2.2 — La fixation des taux de crédit relève de la sphère bancaire, pas du CGA.',1),
(8,'Partie 2 — Cadre juridique et réglementaire','single','Selon l’article 69 du Code des Assurances, le conseiller bancaire qui vend de l’assurance agit :','[{"id":"a","label":"En tant que porteur du risque"},{"id":"b","label":"En tant qu’intermédiaire, dans le cadre d’un mandat donné par la compagnie partenaire"},{"id":"c","label":"En tant qu’expert mandaté par le client"},{"id":"d","label":"Sans statut particulier, la banque étant déjà agréée"}]','["b"]','Module 2.3 — Statut de l’intermédiaire en bancassurance.',1),
(9,'Partie 2 — Cadre juridique et réglementaire','multiple','Quelles obligations découlent du statut d’intermédiaire du conseiller bancaire ?','[{"id":"a","label":"Une habilitation et une formation minimale du personnel bancaire aux produits distribués"},{"id":"b","label":"Une identification claire, pour le client, du rôle de la banque et de celui de la compagnie"},{"id":"c","label":"La libre fixation des commissions par chaque conseiller"},{"id":"d","label":"La traçabilité du conseil donné au client"}]','["a","b","d"]','Module 2.3 — Le commissionnement est fixé par la convention de bancassurance.',1),
(10,'Partie 3 — Devoir de conseil et produits distribués','single','Au titre du devoir de conseil, le client doit recevoir une information claire sur :','[{"id":"a","label":"Le seul montant de la prime"},{"id":"b","label":"Les garanties, les exclusions, la durée, les modalités de résiliation et le coût du produit"},{"id":"c","label":"Les seules garanties souscrites"},{"id":"d","label":"Les seules exclusions du contrat"}]','["b"]','Module 2.4 — Devoir de conseil et d’information.',1),
(11,'Partie 3 — Devoir de conseil et produits distribués','single','Lors d’un crédit immobilier, quelle couverture s’ajoute habituellement à l’assurance emprunteur ?','[{"id":"a","label":"Une assurance voyage"},{"id":"b","label":"Une assurance incendie couvrant le bien financé"},{"id":"c","label":"Une responsabilité civile automobile"},{"id":"d","label":"Une complémentaire santé"}]','["b"]','Module 2.5 — Le bien financé doit également être couvert.',1),
(12,'Partie 3 — Devoir de conseil et produits distribués','single','Dans l’assurance emprunteur, la garantie « IAD » désigne :','[{"id":"a","label":"L’indemnité d’assurance décès"},{"id":"b","label":"L’invalidité absolue et définitive"},{"id":"c","label":"L’incapacité d’activité durable"},{"id":"d","label":"L’indemnisation après déclaration"}]','["b"]','Module 3.1 — Garantie décès et invalidité absolue et définitive.',1),
(13,'Partie 3 — Devoir de conseil et produits distribués','single','Les produits Takaful liés au financement immobilier s’adossent aux formules :','[{"id":"a","label":"Escompte et découvert"},{"id":"b","label":"Mourabaha et Ijara"},{"id":"c","label":"Crédit-bail classique et leasing"},{"id":"d","label":"Épargne-logement et plan d’épargne"}]','["b"]','Module 3.4 — Takaful distribué via les banques islamiques.',1),
(14,'Partie 3 — Devoir de conseil et produits distribués','single','L’argument clé à privilégier pour vendre l’assurance-vie est :','[{"id":"a","label":"Un rendement garanti supérieur à celui de l’or et de l’immobilier"},{"id":"b","label":"Le positionnement comme complément de retraite et outil de transmission"},{"id":"c","label":"Le caractère obligatoire du produit à l’ouverture d’un compte"},{"id":"d","label":"La possibilité de remplacer un crédit immobilier"}]','["b"]','Module 3.2 — Argument clé pour le commercial.',1),
(15,'Partie 4 — Parcours client et rôle du commercial','single','En bancassurance, le « premier client » du commercial de la compagnie est :','[{"id":"a","label":"L’emprunteur qui sollicite un crédit"},{"id":"b","label":"Le conseiller bancaire lui-même"},{"id":"c","label":"Le CGA, en tant qu’autorité de contrôle"},{"id":"d","label":"Le courtier référencé par la banque"}]','["b"]','Module 4.2 — Le rôle du commercial de la compagnie.',1),
(16,'Partie 4 — Parcours client et rôle du commercial','single','À quel moment de vie bancaire correspond la proposition de produits d’épargne assurance-vie ?','[{"id":"a","label":"L’ouverture de compte"},{"id":"b","label":"Un dépôt d’épargne ou une rentrée de fonds"},{"id":"c","label":"L’octroi d’un crédit à la consommation"},{"id":"d","label":"Une demande de chéquier"}]','["b"]','Module 4.1 — Réorientation d’une épargne liquide.',1),
(17,'Partie 5 — Techniques de vente','single','Face à l’objection « c’est trop cher pour mon budget », la piste de réponse recommandée est :','[{"id":"a","label":"Accorder immédiatement une remise commerciale"},{"id":"b","label":"Proposer une garantie modulable ou un capital ajusté, en insistant sur le coût mensuel réel"},{"id":"c","label":"Reporter l’entretien à une date ultérieure"},{"id":"d","label":"Rappeler au client que la souscription est de toute façon obligatoire"}]','["b"]','Module 5.3 — Traitement des objections courantes.',1),
(18,'Partie 5 — Techniques de vente','single','Le cross-selling naturel associé à un crédit immobilier consiste à proposer :','[{"id":"a","label":"Assurance emprunteur et assurance incendie"},{"id":"b","label":"Assurance voyage et assistance"},{"id":"c","label":"Takaful épargne seul"},{"id":"d","label":"Prévoyance individuelle seule"}]','["a"]','Module 5.4 — Vente croisée naturelle.',1),
(19,'Partie 5 — Techniques de vente','single','L’up-selling consiste à :','[{"id":"a","label":"Proposer un produit d’une autre famille au même client"},{"id":"b","label":"Proposer une garantie plus complète en valorisant la protection additionnelle plutôt que le surcoût"},{"id":"c","label":"Réduire le tarif pour emporter la décision"},{"id":"d","label":"Transférer le dossier vers une autre banque partenaire"}]','["b"]','Module 5.4 — Montée en gamme.',1),
(20,'Partie 5 — Techniques de vente','single','Pour un client professionnel ou indépendant, l’approche recommandée met l’accent sur :','[{"id":"a","label":"Des produits d’entrée de gamme simples"},{"id":"b","label":"La prévoyance individuelle et la protection du revenu"},{"id":"c","label":"La sécurisation d’un projet immobilier familial"},{"id":"d","label":"L’assurance voyage liée à la carte bancaire"}]','["b"]','Module 5.5 — Adapter le discours par segment de clientèle.',1)
